-- except-inondation-evacuation-quartier — L'eau monte, certains habitants refusent de partir
SELECT public.fn_cp_import_case('except-inondation-evacuation-quartier', '{"slug": "except-inondation-evacuation-quartier", "title": "L''eau monte, certains habitants refusent de partir", "theme_slug": "situations-exceptionnelles", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 4 heures. Dans un quartier riverain, une crue rapide fait monter le niveau de l''eau de facon visible d''heure en heure. Une evacuation est ordonnee, mais plusieurs habitants refusent de quitter leur domicile, certains invoquant la crainte de laisser leurs biens sans surveillance, d''autres estimant que la montee des eaux ne les atteindra pas. Vous disposez de peu de temps et d''un nombre limite de collegues pour convaincre chaque foyer concerne. Certains logements, en rez-de-chaussee, sont plus immediatement exposes que d''autres situes en etage. La nuit et la montee continue de l''eau compliquent chaque deplacement dans ce quartier.", "questions": [{"position": 1, "max_points": 5, "label": "Comment priorisez-vous vos passages face a ce temps limite et ce nombre d''habitants a convaincre ?", "hint": "Tous les foyers ne courent pas le meme risque dans les memes delais.", "perfect": "Je convaincs et priorise les personnes les plus exposees, cette priorisation restant essentielle compte tenu du temps limite dont je dispose face a cette crue rapide. Je commence par les logements en rez-de-chaussee, immediatement exposes, avant de traiter les etages moins menaces dans l''immediat. Je coordonne cette repartition avec mes collegues pour ne pas dupliquer les passages sur les memes foyers. Je reste attentive a l''evolution de la montee des eaux pour ajuster cette priorisation si necessaire.", "points": [{"position": 1, "label": "Convaincre et prioriser les personnes les plus exposees", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["priorisation effectuee", "personnes exposees", "urgence hierarchisee"]}]}, {"position": 2, "label": "Commencer par les logements en rez-de-chaussee immediatement exposes", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ordre logique de traitement.", "groups": [{"position": 1, "keywords": ["rez-de-chaussee traite", "exposition immediate", "ordre respecte"]}]}, {"position": 3, "label": "Coordonner cette repartition avec les collegues pour eviter les doublons", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Efficacite collective.", "groups": [{"position": 1, "keywords": ["repartition coordonnee", "doublons evites", "efficacite assuree"]}]}, {"position": 4, "label": "Rester attentive a l''evolution de la crue pour ajuster la priorisation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Adaptation continue.", "groups": [{"position": 1, "keywords": ["evolution suivie", "priorisation ajustee", "vigilance continue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment convainquez-vous un habitant qui refuse de partir pour proteger ses biens ?", "hint": "L''attachement aux biens est comprehensible, mais ne doit pas l''emporter sur sa securite vitale.", "perfect": "Je reconnais cette inquietude legitime pour ses biens, sans la balayer d''un revers de main face a l''urgence. Je lui explique clairement le risque vital reel que represente son maintien sur place, sans dramatiser au-dela de ce que la situation impose. Je propose des solutions concretes et rapides, comme mettre en hauteur les objets les plus precieux avant de partir, si le temps le permet encore. Je reste ferme sur la necessite de cette evacuation si le danger devient imminent, quitte a devoir insister davantage.", "points": [{"position": 1, "label": "Reconnaitre l''inquietude pour ses biens sans la balayer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ecoute de la motivation du refus.", "groups": [{"position": 1, "keywords": ["inquietude reconnue", "ecoute accordee", "refus compris"]}]}, {"position": 2, "label": "Expliquer clairement le risque vital reel sans dramatiser au-dela", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Communication proportionnee du danger.", "groups": [{"position": 1, "keywords": ["risque explique", "dramatisation evitee", "danger precise"]}]}, {"position": 3, "label": "Proposer des solutions concretes et rapides si le temps le permet", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Solution pratique proposee.", "groups": [{"position": 1, "keywords": ["solution proposee", "objets mis en hauteur", "temps considere"]}]}, {"position": 4, "label": "Rester ferme si le danger devient imminent", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Fermete finale si necessaire.", "groups": [{"position": 1, "keywords": ["fermete appliquee", "danger imminent", "insistance justifiee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite pour ceux qui, malgre tout, refusent obstinement de partir ?", "hint": "Un refus persistant ne doit pas etre simplement acte sans autre suite.", "perfect": "Je consigne precisement l''identite et l''adresse de ceux qui refusent, cette information restant essentielle pour la suite des secours si la situation s''aggravait. Je transmets cette liste a mon centre operationnel, pour un suivi coordonne avec les autres services engages. Je leur laisse un moyen de contact pour qu''ils puissent alerter en cas d''aggravation soudaine. Je reste attentive a repasser verifier ces foyers si le niveau de l''eau continue de monter significativement.", "points": [{"position": 1, "label": "Consigner precisement l''identite et l''adresse de ceux qui refusent", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilite essentielle pour les secours.", "groups": [{"position": 1, "keywords": ["identite consignee", "adresse notee", "refus documente"]}]}, {"position": 2, "label": "Transmettre cette liste au centre operationnel pour un suivi coordonne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coordination avec les autres services.", "groups": [{"position": 1, "keywords": ["liste transmise", "centre informe", "suivi coordonne"]}]}, {"position": 3, "label": "Laisser un moyen de contact pour une alerte en cas d''aggravation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contact laisse pour la suite.", "groups": [{"position": 1, "keywords": ["contact laisse", "alerte possible", "aggravation anticipee"]}]}, {"position": 4, "label": "Rester attentive a repasser verifier ces foyers si la montee continue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi actif dans le temps.", "groups": [{"position": 1, "keywords": ["passage prevu", "verification prevue", "suivi actif"]}]}]}]}'::jsonb);

-- except-decouverte-restes-humains — Des ossements mis au jour par des travaux
SELECT public.fn_cp_import_case('except-decouverte-restes-humains', '{"slug": "except-decouverte-restes-humains", "title": "Des ossements mis au jour par des travaux", "theme_slug": "situations-exceptionnelles", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 10 heures. Des ouvriers effectuant des travaux de terrassement sur un terrain vague decouvrent des ossements qu''ils vous signalent immediatement. L''anciennete de ces restes est totalement inconnue, allant d''un enfouissement recent a une sepulture ancienne oubliee. Plusieurs curieux, attires par l''arret du chantier, commencent a s''approcher pour observer. Les ouvriers, encore sous le choc de cette decouverte, attendent vos instructions pour savoir s''ils peuvent reprendre leur activite ailleurs sur le chantier. Aucun element ne permet, a ce stade, de determiner s''il s''agit d''une decouverte relevant d''une enquete judiciaire ou d''un site historique.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre premiere action face a cette decouverte dont l''anciennete est inconnue ?", "hint": "Tant que l''anciennete n''est pas etablie, la prudence maximale s''impose.", "perfect": "Je gele les lieux sans rien deplacer, cette abstention totale restant indispensable quelle que soit l''anciennete finalement etablie de ces restes. J''etablis un perimetre large autour de la zone concernee, sans y penetrer davantage que necessaire pour ce constat initial. Je n''autorise aucune reprise des travaux sur cette zone precise, meme si le reste du chantier peut continuer ailleurs. Je sollicite sans delai les services competents pour determiner la nature exacte de cette decouverte.", "points": [{"position": 1, "label": "Geler les lieux sans rien deplacer", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["lieux geles", "deplacement evite", "abstention totale"]}]}, {"position": 2, "label": "Etablir un perimetre large sans y penetrer davantage que necessaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Perimetre proportionne.", "groups": [{"position": 1, "keywords": ["perimetre etabli", "zone protegee", "penetration limitee"]}]}, {"position": 3, "label": "N''autoriser aucune reprise des travaux sur cette zone precise", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Preservation stricte de la zone.", "groups": [{"position": 1, "keywords": ["travaux suspendus", "zone preservee", "reprise refusee"]}]}, {"position": 4, "label": "Solliciter sans delai les services competents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Expertise rapidement mobilisee.", "groups": [{"position": 1, "keywords": ["services sollicites", "expertise demandee", "delai reduit"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous les curieux qui s''approchent, attires par l''arret du chantier ?", "hint": "La curiosite naturelle face a une decouverte macabre ne doit pas compromettre la preservation des lieux.", "perfect": "J''ecarte fermement mais courtoisement ces curieux du perimetre etabli, sans leur donner de details sur la nature de cette decouverte. J''explique brievement, sans entrer dans les details, que ce perimetre repond a une necessite de preservation. Je reste attentive a ce qu''aucune photo ou video ne circule de maniere inappropriee, sans pour autant confisquer des telephones sans base legale. Je maintiens ce perimetre jusqu''a l''arrivee des services competents.", "points": [{"position": 1, "label": "Ecarter fermement mais courtoisement ces curieux du perimetre", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion equilibree des curieux.", "groups": [{"position": 1, "keywords": ["curieux ecartes", "courtoisie maintenue", "fermete appliquee"]}]}, {"position": 2, "label": "Expliquer brievement sans entrer dans les details", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Communication mesuree.", "groups": [{"position": 1, "keywords": ["explication breve", "details evites", "communication mesuree"]}]}, {"position": 3, "label": "Rester attentive aux prises de vue sans confisquer sans base legale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance sans exces de pouvoir.", "groups": [{"position": 1, "keywords": ["vigilance appliquee", "confiscation evitee", "base legale respectee"]}]}, {"position": 4, "label": "Maintenir ce perimetre jusqu''a l''arrivee des services competents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Perimetre tenu jusqu''au relais.", "groups": [{"position": 1, "keywords": ["perimetre maintenu", "relais attendu", "tenue assuree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous les ouvriers, encore sous le choc de cette decouverte, dans l''attente des services competents ?", "hint": "Ces ouvriers restent des temoins directs dont le recit peut s''averer utile, au-dela du choc qu''ils ressentent.", "perfect": "Je prends le temps de recueillir leur recit precis des circonstances de cette decouverte, pendant que ces details restent frais dans leur memoire. Je reste attentive a leur etat, cette decouverte macabre pouvant les affecter davantage qu''ils ne le laissent paraitre. Je leur explique qu''ils ne peuvent reprendre les travaux sur cette zone precise, tout en les autorisant a travailler ailleurs sur le chantier si cela reste possible. Je recueille leurs coordonnees pour un eventuel complement ulterieur.", "points": [{"position": 1, "label": "Recueillir leur recit precis pendant que les details restent frais", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Temoignage recueilli rapidement.", "groups": [{"position": 1, "keywords": ["recit recueilli", "details frais", "circonstances precisees"]}]}, {"position": 2, "label": "Rester attentive a leur etat apres cette decouverte macabre", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attention au choc subi.", "groups": [{"position": 1, "keywords": ["etat considere", "choc reconnu", "attention accordee"]}]}, {"position": 3, "label": "Autoriser la reprise ailleurs sur le chantier si possible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Limitation de l''arret aux seules zones concernees.", "groups": [{"position": 1, "keywords": ["reprise autorisee ailleurs", "zone limitee", "activite maintenue"]}]}, {"position": 4, "label": "Recueillir leurs coordonnees pour un complement ulterieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi facilite.", "groups": [{"position": 1, "keywords": ["coordonnees recueillies", "complement possible", "suivi facilite"]}]}]}]}'::jsonb);

